-- The order-service schema as Hibernate created it before Flyway (#115): the DDL that
-- ddl-auto: update runs on an empty database, written out by Hibernate
-- (jakarta.persistence.schema-generation.scripts.action=update). The databases created
-- before Flyway hold exactly these tables. FlywayMigrationIT loads it and baselines it.

create table cart_items (id bigint generated by default as identity, product_id bigint not null, quantity integer not null check ((quantity>=1)), cart_id bigint not null, primary key (id));
create table carts (id bigint generated by default as identity, user_email varchar(150) not null, primary key (id));
create table order_items (id bigint generated by default as identity, product_id bigint not null, product_name varchar(150) not null, quantity integer not null check ((quantity>=1)), unit_price numeric(10,2) not null, order_id bigint not null, primary key (id));
create table orders (id bigint generated by default as identity, created_at timestamp(6) with time zone not null, status varchar(20) not null check ((status in ('PENDING','PAID','CANCELLED'))), total numeric(12,2) not null, user_email varchar(150) not null, primary key (id));
alter table if exists cart_items drop constraint if exists UK6oue0maw421roerltnxn16a38;
alter table if exists cart_items add constraint UK6oue0maw421roerltnxn16a38 unique (cart_id, product_id);
alter table if exists carts drop constraint if exists UKj32fvm6dplkq8v924ynx105l6;
alter table if exists carts add constraint UKj32fvm6dplkq8v924ynx105l6 unique (user_email);
alter table if exists cart_items add constraint FKpcttvuq4mxppo8sxggjtn5i2c foreign key (cart_id) references carts;
alter table if exists order_items add constraint FKbioxgbv59vetrxe0ejfubep1w foreign key (order_id) references orders;
